saveLyrics: async (path: string, lrc: string, origin: 'manual' | 'auto' = 'manual') => {
  // Register intent before queuing: a pending manual selection invalidates old auto work.
  const key = lyricKey(path);
  const epochAtRequest = getManualEpoch(path);
  if (origin === 'manual') lyricManualEpochs.set(key, epochAtRequest + 1);
  const requestedEpoch = getManualEpoch(path);
  const previous = lyricSaveQueues.get(key) ?? Promise.resolve();
  const job = previous.catch(() => {}).then(async () => {
    // This check executes INSIDE the queue, before the irreversible backend write.
    if (origin === 'auto' && getManualEpoch(path) !== requestedEpoch) return;
    if (origin === 'manual' && getManualEpoch(path) !== requestedEpoch) return;
    await invoke('save_lyrics_file', { path, content: lrc });
    // No other writer for this path may run until readback and state update finish.
    const lines: any = await invoke('get_lyrics', { path });
    if (getManualEpoch(path) !== requestedEpoch) return;
    const currentTrack = get().currentTrack;
    const playbackCurrent = get().playback.current_track;
    const trackUrl = (currentTrack as any)?.url;
    const isCurrent = pathsEqual(playbackCurrent, path)
      || pathsEqual(currentTrack?.path, path)
      || (typeof trackUrl === 'string' && trackUrl ? pathsEqual(trackUrl, path) : false);
    if (isCurrent && Array.isArray(lines)) {
      set({ lyrics: sortLyricLines(lines), lyricStatus: 'found' });
    }
  });
  const tail = job.then(() => {}, () => {});
  lyricSaveQueues.set(key, tail);
  try { await job; } catch (e) { console.error(e); }
  finally { if (lyricSaveQueues.get(key) === tail) lyricSaveQueues.delete(key); }
},

